Actionscript.script:
function gameSave()
{
   trace("saved");
   var _loc1_ = SharedObject.getLocal("bomb_it");
   var _loc2_ = {playerName1:playerName1,playerName2:playerName2,highScore_arr:highScore_arr};
   _loc1_.data.myObj = _loc2_;
}
function upDateStageNum(stageNum)
{
   stageNum_str = "";
   if(stageNum < 10)
   {
      stageNum_str += "0";
   }
   stageNum_str += stageNum;
}
fscommand("allowscale",false);
fscommand("showmenu",false);
_root.localization_url1 = "http://moregames.agame.com/?utm_source=brandedgames&utm_medium=bomb_it";
_root.localization_url2 = "http://freegames.agame.com/?utm_source=brandedgames&utm_medium=bomb_it";
qualityNum = 1;
life0 = 3;
var totalPlayer = 0;
myLSO = SharedObject.getLocal("bomb_it");
if(myLSO.data.myObj == undefined)
{
   trace("first play");
   playerName1 = "";
   playerName2 = "";
   highScore_arr = [["cpu",100],["cpu",137728],["cpu",50000],["cpu",40000],["cpu",30000],["cpu",20000],["cpu",10000],["cpu",5000],["cpu",3000],["cpu",1000]];
   gameSave();
}
else
{
   trace("loaded");
   var myObj = myLSO.data.myObj;
   playerName1 = myObj.playerName1;
   playerName2 = myObj.playerName2;
   highScore_arr = myObj.highScore_arr.slice();
}

stop();
if(bgMusic_sound == undefined)
{
   soundon = true;
   bgMusic_sound = new Sound(this);
   bgMusic_sound.attachSound("Bombit_-_mainscreen");
   bgMusic_sound.start();
   bgMusic_sound.onSoundComplete = function()
   {
      if(soundon)
      {
         this.start();
      }
   };
}
delete p1;
delete p2;
p1 = undefined;
p2 = undefined;

function mov(p, dx)
{
   if(p.setDown)
   {
      return 0;
   }
   var _loc3_;
   if(totalPlayer == 2)
   {
      _loc3_ = this["p" + (3 - p.id)];
      do
      {
         p.heroId += dx;
         if(p.heroId <= 0)
         {
            p.heroId = 4;
         }
         else if(p.heroId > 4)
         {
            p.heroId = 1;
         }
      }
      while(p.heroId == _loc3_.heroId);
   }
   else
   {
      p.heroId += dx;
      if(p.heroId <= 0)
      {
         p.heroId = 4;
      }
      else if(p.heroId > 4)
      {
         p.heroId = 1;
      }
   }
   var _loc4_ = this["p_pointer" + p.id];
   _loc4_.delayTime = 2;
   _loc4_.heroId = p.heroId;
   _loc4_.p.gotoAndStop((p.id - 1) * 4 + p.heroId);
   _loc4_.arrow.gotoAndStop(p.heroId);
   _loc4_._x = this["hero" + p.heroId]._x;
}
var heroNum = 1;
while(heroNum <= 4)
{
   this["heroObj" + heroNum] = {heroId:0,life:1,totalBomb:1,totalScore:0,score:0,killScore:0,timeScore:0,toolScore:0,brickScore:0,bonus:0};
   var hero = this["hero" + heroNum];
   if(heroNum <= totalPlayer)
   {
      var p = this["p" + heroNum];
      var p_pointer = this.attachMovie("p_pointer","p_pointer" + heroNum,heroNum,{heroId:0,delayTime:2,_xscale:200,_yscale:200,_y:hero._y});
      p_pointer.onEnterFrame = function()
      {
         if(--this.delayTime <= 0)
         {
            this.delayTime = 100;
            this._parent["眼皮" + this.heroId].gotoAndPlay(2);
         }
      };
   }
   heroNum++;
}
Key.addListener(this);
totalSetDown = 0;
if(totalPlayer == 1)
{
   heroObj1.life = 3;
   p1 = {setDown:false,id:1,heroId:0,key0:37,key1:38,key2:39,key3:40,fireKey:32};
   mov(p1,1);
   this.onKeyUp = function()
   {
      switch(Key.getCode())
      {
         case p1.key0:
         case p1.key1:
            mov(p1,-1);
            break;
         case p1.key2:
         case p1.key3:
            mov(p1,1);
            break;
         case p1.fireKey:
            gotoAndStop("game");
         default:
            return;
      }
   };
}
else
{
   heroObj1.life = 3;
   heroObj2.life = 3;
   p1 = {setDown:false,id:1,heroId:0,key0:65,key1:87,key2:68,key3:83,fireKey:32};
   p2 = {setDown:false,id:2,heroId:0,key0:37,key1:38,key2:39,key3:40,fireKey:13};
   mov(p1,1);
   mov(p2,1);
   this.onKeyUp = function()
   {
      var _loc0_;
      switch(Key.getCode())
      {
         case p1.key0:
         case p1.key1:
            mov(p1,-1);
            break;
         case p1.key2:
         case p1.key3:
            mov(p1,1);
            break;
         case p1.fireKey:
            if(p1.setDown == false)
            {
               p1.setDown = true;
               p_pointer1.gotoAndStop(1);
               totalSetDown = _loc0_ = totalSetDown + 1;
               if(_loc0_ == totalPlayer)
               {
                  gotoAndStop("game");
               }
            }
            break;
         case p2.key0:
         case p2.key1:
            mov(p2,-1);
            break;
         case p2.key2:
         case p2.key3:
            mov(p2,1);
            break;
         case p2.fireKey:
            if(p2.setDown == false)
            {
               p2.setDown = true;
               p_pointer2.gotoAndStop(1);
               totalSetDown = _loc0_ = totalSetDown + 1;
               if(_loc0_ == totalPlayer)
               {
                  gotoAndStop("game");
               }
            }
         default:
            return;
      }
   };
}
specialToolName_array = ["火箭","地雷","手榴弹","汽弹","冰箭","火焰箭"];
specialToolId = 6;
bgMusic_array = ["Bombit_-_level_1","Bombit_-_level_2","Bombit_-_level_3","Bombit_-_level_4"];
bgMusicId = 4;

stageNum = 0;
var heroNum = 1;
while(heroNum <= 4)
{
   var heroObj = this["heroObj" + heroNum];
   heroObj.totalScore = 0;
   if(heroNum <= totalPlayer)
   {
      heroObj.life = 3;
   }
   else
   {
      heroObj.life = 1;
   }
   heroNum++;
}
p_pointer1.removeMovieClip();
p_pointer2.removeMovieClip();
bgMusic_sound.stop();
Key.removeListener(this);
quality_mc.gotoAndStop(qualityNum);
if(soundon)
{
   soundon_mc.stop();
}
else
{
   soundon_mc.nextFrame();
}
switch(varHard)
{
   case "easy":
      totalStage = 15;
      break;
   case "normal":
      totalStage = 20;
      break;
   case "hard":
      totalStage = 25;
}
trace("varHard=" + varHard + ",totalStage=" + totalStage);

nameOutput = "";
scoreOutput = "";
var L = highScore_arr.length;
var i = 0;
while(i < L)
{
   var j = i;
   while(j < L)
   {
      if(highScore_arr[i][1] < highScore_arr[j][1])
      {
         var temp = highScore_arr[i][0];
         highScore_arr[i][0] = highScore_arr[j][0];
         highScore_arr[j][0] = temp;
         var temp = highScore_arr[i][1];
         highScore_arr[i][1] = highScore_arr[j][1];
         highScore_arr[j][1] = temp;
      }
      j++;
   }
   i++;
}
if(L > 10)
{
   L = 10;
}
var i = 0;
while(i < L)
{
   var playerName = highScore_arr[i][0];
   var highScore = highScore_arr[i][1];
   this["name" + (i + 1)] = playerName;
   this["score" + (i + 1)] = highScore;
   var j = 0;
   while(j <= totalPlayer)
   {
      if(playerName == this["playerName" + j] && highScore == this["heroObj" + j].totalScore)
      {
         break;
      }
      j++;
   }
   if(j > totalPlayer)
   {
      this["new" + i]._visible = false;
   }
   else
   {
      this["new" + i]._visible = true;
   }
   i++;
}
gameSave();

nameOutput = "";
scoreOutput = "";
var L = highScore_arr.length;
var i = 0;
while(i < L)
{
   var j = i;
   while(j < L)
   {
      if(highScore_arr[i][1] < highScore_arr[j][1])
      {
         var temp = highScore_arr[i][0];
         highScore_arr[i][0] = highScore_arr[j][0];
         highScore_arr[j][0] = temp;
         var temp = highScore_arr[i][1];
         highScore_arr[i][1] = highScore_arr[j][1];
         highScore_arr[j][1] = temp;
      }
      j++;
   }
   i++;
}
if(L > 10)
{
   L = 10;
}
var i = 0;
while(i < L)
{
   var playerName = highScore_arr[i][0];
   var highScore = highScore_arr[i][1];
   this["name" + (i + 1)] = playerName;
   this["score" + (i + 1)] = highScore;
   var j = 0;
   while(j <= totalPlayer)
   {
      if(playerName == this["playerName" + j] && highScore == this["heroObj" + j].totalScore)
      {
         break;
      }
      j++;
   }
   if(j > totalPlayer)
   {
      this["new" + i]._visible = false;
   }
   else
   {
      this["new" + i]._visible = true;
   }
   i++;
}
gameSave();

on(release, keyPress "p"){
   pause_mc.play();
   game.pause();
   timer.timePause();
}
on(keyPress "P"){
   pause_mc.play();
   game.pause();
   timer.timePause();
}

on(release){
   if(soundon)
   {
      game.bgMusic_sound.stop();
      soundon = false;
      soundon_mc.nextFrame();
   }
   else
   {
      game.bgMusic_sound.start();
      soundon = true;
      soundon_mc.prevFrame();
   }
}
